export class VideoAdDetector {
    constructor() {
        this.adKeywords = ["广告", "跳过", "ad", "skip", "annons", "reklama", "publicité", "anuncio", "werbung", "реклама", "広告", "광고", "skip ad", "skip intro", "skip ads"];
        this.lastSourceChangeTime = 0;
        this.sourceChanges = [];
        this.adDetected = false;
        this.lastVideoSrc = null;
    }

    isAdVideo(mainVideo, previousMainVideo) {
        // 检查周围元素中的广告关键词
        const containsAdKeyword = this.checkAdKeywords(mainVideo);

        // 检查视频时长 (潜在的广告)
        const isShortVideo = mainVideo.duration > 0 && mainVideo.duration <= 60;

        // 检查静音自动播放 (常见于广告)
        const isMutedAutoplay = mainVideo.muted && mainVideo.autoplay;

        // 检查覆盖元素
        const hasOverlay = this.checkOverlay(mainVideo);

        // 检查快速源变化
        const hasRapidSourceChange = this.checkRapidSourceChange(mainVideo);

        // 检查视频是否意外更改
        const isUnexpectedChange = this.checkUnexpectedChange(mainVideo, previousMainVideo);

        // 检查特定的广告相关类或属性
        const hasAdAttributes = this.checkAdAttributes(mainVideo);

        // 综合判断
        const likelyAd = (containsAdKeyword && isShortVideo) ||
            (isShortVideo && isMutedAutoplay && (hasOverlay || hasRapidSourceChange)) ||
            (isUnexpectedChange) || (isShortVideo && hasAdAttributes);

        // 如果检测到广告，设置标志
        if (likelyAd) {
            this.adDetected = true;
        }

        return likelyAd;
    }

    checkAdKeywords(video) {
        const elementsToCheck = this.getRelevantElements(video);
        return elementsToCheck.some(element =>
            this.adKeywords.some(keyword =>
                (element.textContent && element.textContent.toLowerCase().includes(keyword.toLowerCase())) ||
                (element.placeholder && element.placeholder.toLowerCase().includes(keyword.toLowerCase())) ||
                (typeof element.value === 'string' && element.value.toLowerCase().includes(keyword.toLowerCase())) ||
                (element.alt && element.alt.toLowerCase().includes(keyword.toLowerCase())) ||
                (element.title && element.title.toLowerCase().includes(keyword.toLowerCase()))
            )
        );
    }

    getRelevantElements(video) {
        let elements = [];
        let currentWindow = video.ownerDocument.defaultView;
        let currentDocument = video.ownerDocument;

        // 检查视频的父元素及其兄弟元素
        if (video.parentElement) {
            elements = [video.parentElement, ...video.parentElement.children];
        }

        // 检查视频容器的父元素（如果存在）
        const videoContainer = this.findVideoContainer(video);
        if (videoContainer && videoContainer !== video.parentElement) {
            elements = [...elements, videoContainer, ...videoContainer.children];
        }

        // 检查与视频父级元素存在视觉交集的元素
        const allElements = document.body.getElementsByTagName('*');
        const videoRect = video.getBoundingClientRect();
        for (let element of allElements) {
            const elementRect = element.getBoundingClientRect();
            if (!(elementRect.right < videoRect.left ||
                elementRect.left > videoRect.right ||
                elementRect.bottom < videoRect.top ||
                elementRect.top > videoRect.bottom)) {
                elements.push(element);
            }
        }

        return elements;
    }

    findVideoContainer(video) {
        let container = video.parentElement;
        const videoRect = video.getBoundingClientRect();
        while (container && container !== document.body) {
            const containerRect = container.getBoundingClientRect();
            const isLargerThanVideo = containerRect.width > videoRect.width && containerRect.height > videoRect.height;
            const isNotFloating = getComputedStyle(container).position !== 'fixed' && getComputedStyle(container).position !== 'absolute';
            if (isLargerThanVideo && isNotFloating) {
                return container;
            }
            container = container.parentElement;
        }
        return null;
    }

    checkOverlay(video) {
        const elementsToCheck = this.getRelevantElements(video);
        return elementsToCheck.some(element =>
            element.tagName.toLowerCase() === 'div' &&
            (parseInt(getComputedStyle(element).zIndex) > 1000 ||
                getComputedStyle(element).position === 'absolute' ||
                getComputedStyle(element).position === 'fixed')
        );
    }

    checkRapidSourceChange(video) {
        const now = Date.now();
        if (video.src !== this.lastVideoSrc) {
            this.sourceChanges.push(now);
            this.lastVideoSrc = video.src;

            // 只保留最近30秒内的源变化记录
            this.sourceChanges = this.sourceChanges.filter(time => now - time <= 30000);

            // 如果检测到广告结束，重置状态
            if (this.adDetected && this.sourceChanges.length > 1) {
                const timeSinceLastChange = now - this.sourceChanges[this.sourceChanges.length - 2];
                if (timeSinceLastChange > 5000) {  // 如果距离上次变化超过5秒，可能是广告结束
                    this.adDetected = false;
                    this.sourceChanges = [now];  // 重置为只包含当前变化
                    return false;
                }
            }
        }

        // 检查是否在20秒内发生了3次或更多的源变化
        return this.sourceChanges.length >= 3 &&
            (now - this.sourceChanges[this.sourceChanges.length - 3]) <= 20000;
    }

    checkUnexpectedChange(mainVideo, previousMainVideo) {
        return previousMainVideo &&
            !previousMainVideo.ended &&
            mainVideo !== previousMainVideo &&
            Math.abs(mainVideo.duration - previousMainVideo.duration) > 30;  // 新旧视频时长差异大
    }

    checkAdAttributes(video) {
        const videoSrc = video.getAttribute('src');
        let hostnameContainsAd = false;

        if (videoSrc) {
            try {
                const url = new URL(videoSrc);
                hostnameContainsAd = url.hostname.includes('ad') || url.hostname.includes('ads') || url.hostname.includes('advertise');
            } catch (e) {
                if (videoSrc.startsWith('blob:')) {
                    console.warn('Blob URL detected, skipping hostname check:', videoSrc);
                } else {
                    console.error('Error parsing video src URL:', e);
                }
            }
        }
        return video.hasAttribute('data-ad') ||
            video.classList.contains('ad-video') ||
            hostnameContainsAd ||
            (video.parentElement && video.parentElement.classList.contains('ad-container'));
    }
}

