import { fromUrl, parseDomain } from "parse-domain";
import { orderBy, toString } from "lodash-es";



export function getDomainFromUrl(url) {
  if (!url || !isValidUrl(url)) return url ? toString(url).substring(0, 20) : "";
  const domainInfo = parseDomain(fromUrl(url));
  return `${domainInfo.domain}.${domainInfo.topLevelDomains?.join(".")}`;
}

export function getHostnameFromUrl(url) {
  try {
    return new URL(url).hostname;
  } catch (e) {
    // console.error(`getHostnameFromUrl ${url} error`, e);
    return url ? toString(url).substring(0, 20) : "";
  }
}

export const isValidUrl = (string) => {
  const regex = /^https?:\/\/.+/;
  return regex.test(string);
};

export function getChromeVersion() {
  const raw = navigator.userAgent.match(/Chrom(?:e|ium)\/([0-9]+)\./);
  return raw ? parseInt(raw[1], 10) : false;
}

export const replaceAndAddObjectsByKey = (arrayA, arrayB, key = 'name') => {
  const keysInA = new Set(arrayA.map(obj => obj[key]));

  const updatedArrayA = arrayA.map(objA => {
    const objB = arrayB.find(objB => objB[key] === objA[key]);
    return objB || objA;
  });

  arrayB.forEach(objB => {
    if (!keysInA.has(objB[key])) {
      updatedArrayA.push(objB);
    }
  });
  return updatedArrayA;
};

export const asyncSleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

export async function copyTextToClipboard(text) {
  if (navigator.clipboard) {
    try {
      await navigator.clipboard.writeText(text);
      return true;
    } catch {
      return false;
    }
  }

  const textArea = document.createElement("textarea");
  textArea.value = text;
  textArea.style.cssText = "position:fixed;opacity:0";
  document.body.appendChild(textArea);
  textArea.focus();
  textArea.select();

  let successful = false;
  try {
    successful = document.execCommand("copy");
  } catch (err) {
    console.error("copyTextToClipboard error", err);
  }
  document.body.removeChild(textArea);
  return successful;
}

export function hexToRgb(hex, alpha = 1) {
  hex = hex.replace("#", "").trim()
  let r = parseInt(hex.substr(0, 2), 16);
  let g = parseInt(hex.substr(2, 2), 16);
  let b = parseInt(hex.substr(4, 2), 16);
  return `rgb(${r}, ${g}, ${b},${alpha})`;
}

export const filterTabs = (tabs, searchText, orderByParam, sortBy, activeWindowId) => {
  let filteredTabs = [...tabs];

  if (activeWindowId) {
    filteredTabs = filteredTabs.map(tab => ({
      ...tab,
      inActiveWindow: tab.windowId === activeWindowId ? 1 : 0
    }));
    filteredTabs = orderBy(filteredTabs, ["inActiveWindow", sortBy], ['desc', orderByParam]);
  } else if (orderByParam && sortBy) {
    filteredTabs = orderBy(filteredTabs, [sortBy], [orderByParam]);
  }

  if (searchText.trim()) {
    const keywords = searchText.trim().toLowerCase().split(/\s+/);
    filteredTabs = filteredTabs.filter(tab =>
      keywords.every(kw =>
        (tab.url?.toLowerCase().includes(kw) || tab.title?.toLowerCase().includes(kw))
      )
    );
  }

  return filteredTabs;
};

export function calculateClockAngle() {
  const now = new Date();
  const hours = now.getHours() % 12;
  const minutes = now.getMinutes();

  const hourAngle = (hours + minutes / 60) * 30;
  const minuteAngle = minutes * 6;

  return Math.abs(hourAngle - minuteAngle);
}

export const formatDuration = (duration) => {
  if (duration == null) return "00:00";

  const numDuration = Number(duration);
  if (isNaN(numDuration) || numDuration < 0) return "00:00";
  if (!isFinite(numDuration) || numDuration > 86400) return '∞';

  const roundedDuration = Math.floor(numDuration);
  const hours = Math.floor(roundedDuration / 3600);
  const minutes = Math.floor((roundedDuration % 3600) / 60);
  const seconds = roundedDuration % 60;

  return hours > 0
    ? `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
    : `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
};

export const formatDateYmdHis = (date) => {
  const targetDate = new Date(date);
  if (isNaN(targetDate)) {
    console.error("Invalid date");
    return "";
  }

  const pad = num => String(num).padStart(2, '0');
  const Y = targetDate.getFullYear();
  const m = pad(targetDate.getMonth() + 1);
  const d = pad(targetDate.getDate());
  const hh = pad(targetDate.getHours());
  const mm = pad(targetDate.getMinutes());
  const ss = pad(targetDate.getSeconds());

  return `${Y}-${m}-${d} ${hh}:${mm}:${ss}`;
};

export function formatLocalTime(timestamp = Date.now(), locale = null) {
  try {
    // Get user's timezone and locale
    const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const userLocale = locale || navigator.language || 'en-US';

    // Format date using native Intl.DateTimeFormat
    const formatter = new Intl.DateTimeFormat(userLocale, {
      timeZone,
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: 'numeric',
      second: 'numeric'
    });

    return formatter.format(new Date(timestamp));
  } catch (error) {
    console.error('Error formatting local time:', error);
    return new Date(timestamp).toLocaleString();
  }
}

export function faviconURL(u, size = 32) {
  if (!u) return '';
  try {
    const url = new URL(u);
    if (url.protocol === 'http:' || url.protocol === 'https:') {
      return `https://api.faviconkit.com/${url.hostname}/${size}`;
    } else {
      const faviconUrl = new URL(chrome.runtime.getURL("/_favicon/"));
      faviconUrl.searchParams.set("pageUrl", u);
      faviconUrl.searchParams.set("size", size);
      return faviconUrl.toString();
    }
  } catch (e) {
    const faviconUrl = new URL(chrome.runtime.getURL("/_favicon/"));
    faviconUrl.searchParams.set("pageUrl", u);
    faviconUrl.searchParams.set("size", size);
    return faviconUrl.toString();
  }
}

export const scrollToActiveTab = () => {
  document.querySelector('.tab-item.active')?.scrollIntoView({
    behavior: "instant",
    block: "center",
    inline: "nearest"
  });
};

export const decodedUrl = (url, full = true) => {
  try {
    const decoded = decodeURIComponent(url);
    if (full) return decoded;

    const urlObj = new URL(decoded);
    return urlObj.pathname + urlObj.search + urlObj.hash;
  } catch (e) {
    console.error(`Invalid URL: ${url}`, e);
    return url;
  }
};

export const getBrowser = () => {
  const userAgent = navigator.userAgent.toLowerCase();
  const browserInfo = navigator.userAgentData?.brands?.[0];

  if (browserInfo?.brand) return browserInfo.brand;

  const browsers = {
    firefox: "Firefox",
    edg: "Edge",
    opr: "Opera",
    opera: "Opera",
    chrome: "Chrome",
    safari: "Safari",
    vivaldi: "Vivaldi",
    brave: "Brave",
    yandex: "Yandex",
    seamonkey: "SeaMonkey",
    chromium: "Chromium",
    whale: "Naver Whale",
    tor: "Tor Browser",
    maxthon: "Maxthon"
  };

  for (const [key, value] of Object.entries(browsers)) {
    if (userAgent.includes(key)) return value;
  }

  return "Unknown";
};

export function getShortBrowserName() {
  const userAgent = navigator.userAgent;
  const platform = navigator.platform;

  // Use standard abbreviations or full names
  const browserName = userAgent.includes('Firefox') ? 'Firefox' :
    userAgent.includes('Edg/') ? 'Edge' :
      userAgent.includes('OPR/') || userAgent.includes('Opera') ? 'Opera' :
        userAgent.includes('Chrome') ? 'Chrome' :
          userAgent.includes('Safari') ? 'Safari' :
            'Unknown';

  // Common platform abbreviations
  const platformShort = platform.includes('Win') ? 'Win' :    // Windows 的标准缩写
    platform.includes('Mac') ? 'macOS' :   // macOS 通常不缩写
      platform.includes('Linux') ? 'Linux' : // Linux 通常不缩写
        'Unknown';

  // Add screen width for better device identification
  const screenWidth = window.screen.width;

  // Add random 2-character suffix for uniqueness
  const randomSuffix = Math.random().toString(36).substring(2, 4);

  return `${browserName}-${platformShort}-${screenWidth}-${randomSuffix}`;
}

export const countBookmarkUrls = (bookmark) => {
  if (bookmark.url) return 1;
  if (bookmark.children) {
    return bookmark.children.reduce((count, child) => count + countBookmarkUrls(child), 0);
  }
  return 0;
};

export function isUsableVideo(video) {
  const rect = video.getBoundingClientRect();

  if (rect.width < 200 || rect.height < 200 || (rect.width > rect.height && rect.height / rect.width > 2.4)) {
    return false;
  }

  const isBottomRightQuarter = rect.right >= window.innerWidth * 0.75 && rect.bottom >= window.innerHeight * 0.75;
  const isSmallVideo = rect.width * rect.height <= window.innerWidth * window.innerHeight * 0.25;

  if (isBottomRightQuarter && isSmallVideo) {
    return false;
  }

  const duration = video.duration;
  return duration >= 10 || duration === Infinity || isNaN(duration);
}

export function calcSliderPos(e) {
  return (e.offsetX / e.target.clientWidth) * parseInt(e.target.getAttribute('max'), 10);
}

function isElementInViewport(element) {
  return new Promise(resolve => {
    const observer = new IntersectionObserver(([entry]) => {
      resolve(entry.isIntersecting);
      observer.disconnect();
    });
    observer.observe(element);
  });
}

export const addEventListenersOnce = (element, event, handler) => {
  element.removeEventListener(event, handler);
  element.addEventListener(event, handler);
};

const elementPositions = new Map();

export function saveElementPosition(element) {
  const parent = element.parentElement;
  const index = Array.from(parent.children).indexOf(element);
  elementPositions.set(element, { parent, index });
}

export function restoreElementPosition(element) {
  const position = elementPositions.get(element);
  if (!position) {
    console.error('No saved position for element:', element);
    return;
  }

  const { parent, index } = position;
  const children = Array.from(parent.children);

  if (index >= children.length) {
    parent.appendChild(element);
  } else {
    parent.insertBefore(element, children[index]);
  }
  console.log('Element restored to original position:', element, position);
}


export function recordDebugLog(...args) {
  // Skip logging in production environments
  if (process.env.NODE_ENV === 'production' || process.env.NODE_ENV === 'pre_release') return;

  // Only format args if we're actually going to log
  console.debug(
    `[${new Date().toISOString()}]`,
    ...args.map(arg => typeof arg === 'object' ? JSON.stringify(arg, null, 2) : String(arg))
  );
}



export const mergeData = (data1, data2, compareFields = []) => {
  // Handle object merging
  if (typeof data1 === 'object' && typeof data2 === 'object' && !Array.isArray(data1) && !Array.isArray(data2)) {
    const result = { ...data1 };
    for (const key in data2) {
      if (Array.isArray(data2[key])) {
        result[key] = mergeData(data1[key], data2[key], compareFields);
      } else if (typeof data2[key] === 'object' && data2[key] !== null) {
        result[key] = mergeData(data1[key], data2[key], compareFields);
      } else {
        result[key] = data2[key] ?? data1[key];
      }
    }
    return result;
  }

  // Handle array merging
  if (Array.isArray(data1) || Array.isArray(data2)) {
    const array1 = Array.isArray(data1) ? data1 : [];
    const array2 = Array.isArray(data2) ? data2 : [];

    if (array1.length === 0 && array2.length === 0) return [];

    if (typeof array1[0] !== 'object' && typeof array2[0] !== 'object') {
      return [...new Set([...array1, ...array2])];
    }

    if (compareFields.length === 0) {
      return [...array1, ...array2];
    }

    const mergedArray = [...array1];
    array2.forEach(item2 => {
      const existingItemIndex = mergedArray.findIndex(item1 =>
        compareFields.every(field => item1[field] === item2[field])
      );
      if (existingItemIndex === -1) {
        mergedArray.push(item2);
      } else {
        mergedArray[existingItemIndex] = mergeData(mergedArray[existingItemIndex], item2, compareFields);
      }
    });

    return mergedArray;
  }

  // Handle primitive types
  return data2 ?? data1;
};