/**
 * Shows a custom alert dialog with beautiful styling and animations
 * @param {string} message - Text to display in the alert
 * @param {Object} options - Configuration options
 * @param {string} [options.button1Text] - Text for first button
 * @param {Function} [options.button1Callback] - Callback for first button
 * @param {string} [options.button1Icon] - Icon HTML for first button
 * @param {string} [options.button2Text] - Text for second button
 * @param {Function} [options.button2Callback] - Callback for second button
 * @param {string} [options.button2Icon] - Icon HTML for second button
 * @param {boolean} [options.closeOnOutsideClick=true] - Whether clicking outside closes the alert
 * @param {(string|HTMLElement)} [options.wrapper=document.body] - Wrapper element or CSS selector to append alert to
 * @param {string} [options.width='400px'] - Width of alert dialog
 * @param {number} [options.autoCloseDelay] - Auto close delay in milliseconds
 * @param {boolean} [options.useBackdrop=false] - Whether to use backdrop blur effect
 * @returns {Object} Object containing alert instance and close function
 */
export function showCustomAlert(message, options = {}) {
    try {
        if (!message) {
            throw new Error('Message is required');
        }

        const {
            button1Text,
            button1Callback,
            button1Icon,
            button2Text,
            button2Callback,
            button2Icon,
            closeOnOutsideClick = true,
            width = '360px',
            autoCloseDelay,
            useBackdrop = false
        } = options;

        // Get wrapper element
        let wrapper;
        if (options.wrapper instanceof HTMLElement) {
            wrapper = options.wrapper;
        } else if (typeof options.wrapper === 'string') {
            wrapper = document.querySelector(options.wrapper);
        } else {
            wrapper = document.body;
        }

        console.log("wrapper", wrapper, options);

        if (!wrapper || !(wrapper instanceof HTMLElement)) {
            console.warn('Invalid wrapper. Using document.body instead.');
            wrapper = document.body;
        }

        // Remove any existing alerts in the wrapper
        try {
            const existingAlerts = wrapper?.querySelectorAll?.('.vertitab-alert-container') ?? [];
            existingAlerts.forEach(alert => wrapper.contains(alert) && wrapper.removeChild(alert));
        } catch (err) {
            console.error('Error removing existing alerts:', err);
        }

        // Create alert elements with enhanced styling
        let alertContent;
        if (useBackdrop) {
            const alertContainer = createAlertContainer(true);
            alertContainer.classList.add('vertitab-alert-container');
            alertContent = createAlertContent(width, true);
            alertContainer.appendChild(alertContent);
            alertContent = alertContainer;
        } else {
            alertContent = createAlertContent(width, false);
            alertContent.classList.add('vertitab-alert-container');
            alertContent.style.position = 'absolute';
            alertContent.style.top = '50%';
            alertContent.style.left = '50%';
            alertContent.style.transform = 'translate(-50%, -50%)';
        }

        // Create close function with smooth animation
        const closeAlert = () => {
            try {
                if (alertContent) {
                    alertContent.style.opacity = '0';
                    alertContent.style.transform = useBackdrop ? 'scale(0.95)' : 'translate(-50%, -50%) scale(0.95)';
                    setTimeout(() => {
                        if (wrapper?.contains(alertContent)) {
                            wrapper.removeChild(alertContent);
                        }
                    }, 250);
                }
            } catch (err) {
                console.error('Error closing alert:', err);
            }
        };

        // Add elegant close button
        const closeButton = createCloseButton(closeAlert);
        (useBackdrop ? alertContent.children[0] : alertContent).appendChild(closeButton);

        // Create stylish countdown element
        let countdownElement;
        let countdownInterval;
        if (autoCloseDelay && autoCloseDelay > 0) {
            countdownElement = document.createElement('div');
            countdownElement.style.cssText = `
                position: absolute;
                top: 12px;
                left: 12px;
                font-size: 12px;
                color: rgba(255, 255, 255, 0.8);
                background: rgba(0, 0, 0, 0.1);
                padding: 3px 10px;
                border-radius: 6px;
                backdrop-filter: blur(4px);
            `;
            (useBackdrop ? alertContent.children[0] : alertContent).appendChild(countdownElement);

            let remainingTime = Math.ceil(autoCloseDelay / 1000);
            const updateCountdown = () => {
                countdownElement.textContent = `${remainingTime}s`;
                remainingTime--;
                if (remainingTime < 0) {
                    clearInterval(countdownInterval);
                    closeAlert();
                }
            };
            updateCountdown();
            countdownInterval = setInterval(updateCountdown, 1000);
        }

        // Add message with enhanced typography
        (useBackdrop ? alertContent.children[0] : alertContent).appendChild(createMessageElement(message));

        // Add beautifully styled action buttons
        const buttonContainer = createButtonContainer();
        addButtons(
            buttonContainer,
            button1Text,
            async () => {
                if (button1Callback) {
                    try {
                        const result = await button1Callback();
                        if (result !== false) {
                            if (countdownInterval) clearInterval(countdownInterval);
                            closeAlert();
                        }
                    } catch (error) {
                        console.error('Error in button1 callback:', error);
                        if (countdownInterval) clearInterval(countdownInterval);
                        closeAlert();
                    }
                }
            },
            button1Icon,
            button2Text,
            async () => {
                if (button2Callback) {
                    try {
                        const result = await button2Callback();
                        if (result !== false) {
                            if (countdownInterval) clearInterval(countdownInterval);
                            closeAlert();
                        }
                    } catch (error) {
                        console.error('Error in button2 callback:', error);
                        if (countdownInterval) clearInterval(countdownInterval);
                        closeAlert();
                    }
                }
            },
            button2Icon
        );

        if (buttonContainer.children.length > 0) {
            (useBackdrop ? alertContent.children[0] : alertContent).appendChild(buttonContainer);
        }

        // Add smooth outside click handler
        if (closeOnOutsideClick) {
            addOutsideClickHandler(alertContent, wrapper, countdownInterval);
        }

        // Append to wrapper with entrance animation
        try {
            alertContent.style.opacity = '0';
            alertContent.style.transform = useBackdrop ? 'scale(0.95)' : 'translate(-50%, -50%) scale(0.95)';

            if (wrapper) {
                wrapper.appendChild(alertContent);
            } else {
                console.warn('Invalid wrapper. Appending to document.body instead.');
                document.body.appendChild(alertContent);
            }

            // Trigger entrance animation
            requestAnimationFrame(() => {
                alertContent.style.opacity = '1';
                alertContent.style.transform = useBackdrop ? 'scale(1)' : 'translate(-50%, -50%) scale(1)';
            });
        } catch (err) {
            console.error('Error appending alert:', err);
            document.body.appendChild(alertContent);
        }

        // Auto close with fade-out animation
        if (autoCloseDelay && autoCloseDelay > 0) {
            setTimeout(() => {
                if (countdownInterval) clearInterval(countdownInterval);
                closeAlert();
            }, autoCloseDelay);
        }

        return {
            close: () => {
                if (countdownInterval) clearInterval(countdownInterval);
                closeAlert();
            },
            container: alertContent,
            content: useBackdrop ? alertContent.children[0] : alertContent
        };

    } catch (err) {
        console.error('Error showing custom alert:', err);
        return null;
    }
}

/**
 * Clears all alerts from the document
 * @param {(string|HTMLElement)} [wrapper=document.body] - Wrapper element or CSS selector to clear alerts from
 */
export function clearAllAlerts() {
    try {
        const alerts = document.body.querySelectorAll('.vertitab-alert-container');
        alerts.forEach(alert => {
            alert.remove();
        });
    } catch (err) {
        console.error('Error clearing alerts:', err);
    }
}

function createAlertContainer(useBackdrop = false) {
    try {
        const container = document.createElement('div');
        container.style.cssText = `
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.5);
            ${useBackdrop ? 'backdrop-filter: blur(8px);' : ''}
            display: flex;
            justify-content: center;
            align-items: center;
            z-index: 9999;
            animation: fadeIn 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            transition: opacity 0.25s ease, transform 0.25s cubic-bezier(0.4, 0, 0.2, 1);
        `;
        return container;
    } catch (err) {
        console.error('Error creating alert container:', err);
        throw err;
    }
}

function createAlertContent(width, useBackdrop = false) {
    try {
        const content = document.createElement('div');
        content.style.cssText = `
            background: rgba(255, 255, 255, 0.12);
            padding: 32px;
            border-radius: 12px;
            text-align: center;
            position: relative;
            box-shadow: 0 12px 42px rgba(0, 0, 0, 0.12), 0 4px 10px rgba(0, 0, 0, 0.08);
            backdrop-filter: blur(8px);
            -webkit-backdrop-filter: blur(16px);
            border: 1px solid rgba(255, 255, 255, 0.15);
            width: ${width || '360px'};
            max-width: 90%;
            animation: slideIn 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
            transform-origin: center;
            z-index: 10000;
            color: #fff;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            &:hover {
                box-shadow: 0 16px 48px rgba(0, 0, 0, 0.16), 0 6px 12px rgba(0, 0, 0, 0.1);
                transform: translateY(-2px);
            }
        `;
        return content;
    } catch (err) {
        console.error('Error creating alert content:', err);
        throw err;
    }
}

function createCloseButton(onClose) {
    try {
        const button = document.createElement('button');
        button.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M18 6L6 18" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M6 6L18 18" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
        button.style.cssText = `
            position: absolute;
            top: 8px;
            right: 8px;
            background: rgba(255, 255, 255, 0.08);
            border: none;
            cursor: pointer;
            color: rgba(255, 255, 255, 0.7);
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            width: 28px;
            height: 28px;
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 50%;
            outline: none;
            backdrop-filter: blur(4px);
        `;
        button.addEventListener('click', onClose);
        button.addEventListener('mouseover', () => {
            button.style.backgroundColor = 'rgba(255, 255, 255, 0.15)';
            button.style.transform = 'rotate(90deg)';
        });
        button.addEventListener('mouseout', () => {
            button.style.backgroundColor = 'rgba(255, 255, 255, 0.08)';
            button.style.transform = 'rotate(0deg)';
        });
        return button;
    } catch (err) {
        console.error('Error creating close button:', err);
        throw err;
    }
}

function createMessageElement(message) {
    try {
        const element = document.createElement('p');
        element.textContent = message || '';
        element.style.cssText = `
            font-size: 16px;
            color: rgba(255, 255, 255, 0.92);
            margin: 12px 0 24px;
            line-height: 1.6;
            font-weight: 400;
            letter-spacing: 0.15px;
        `;
        return element;
    } catch (err) {
        console.error('Error creating message element:', err);
        throw err;
    }
}

function createButtonContainer() {
    try {
        const container = document.createElement('div');
        container.style.cssText = `
            display: flex;
            justify-content: center;
            gap: 16px;
            margin-top: 12px;
        `;
        return container;
    } catch (err) {
        console.error('Error creating button container:', err);
        throw err;
    }
}

function createButton(text, callback, icon, color, hoverColor) {
    try {
        const button = document.createElement('button');
        button.innerHTML = icon ? `${icon}<span style="margin-left: 8px">${text || ''}</span>` : (text || '');
        button.style.cssText = `
            padding: 10px 24px;
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            border: none;
            border-radius: 6px;
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            background-color: ${color};
            color: white;
            box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
            transform: translateY(0);
            display: flex;
            align-items: center;
            justify-content: center;
            letter-spacing: 0.25px;
            backdrop-filter: blur(4px);
        `;
        if (callback) {
            button.addEventListener('click', callback);
        }
        button.addEventListener('mouseover', () => {
            button.style.backgroundColor = hoverColor;
            button.style.transform = 'translateY(-2px)';
            button.style.boxShadow = '0 6px 20px rgba(0, 0, 0, 0.16)';
        });
        button.addEventListener('mouseout', () => {
            button.style.backgroundColor = color;
            button.style.transform = 'translateY(0)';
            button.style.boxShadow = '0 4px 16px rgba(0, 0, 0, 0.12)';
        });
        return button;
    } catch (err) {
        console.error('Error creating button:', err);
        throw err;
    }
}

function addButtons(container, button1Text, button1Callback, button1Icon, button2Text, button2Callback, button2Icon) {
    try {
        if (button1Text && button1Callback) {
            container.appendChild(createButton(button1Text, button1Callback, button1Icon, 'rgba(76, 175, 80, 0.85)', 'rgba(69, 160, 73, 0.9)'));
        }
        if (button2Text && button2Callback) {
            container.appendChild(createButton(button2Text, button2Callback, button2Icon, 'rgba(244, 67, 54, 0.85)', 'rgba(218, 25, 11, 0.9)'));
        }
    } catch (err) {
        console.error('Error adding buttons:', err);
    }
}

function addOutsideClickHandler(container, wrapper, countdownInterval) {
    try {
        container.addEventListener('click', (event) => {
            if (event.target === container) {
                try {
                    if (countdownInterval) clearInterval(countdownInterval);
                    container.style.opacity = '0';
                    container.style.transform = 'scale(0.95)';
                    setTimeout(() => {
                        if (wrapper?.contains(container)) {
                            wrapper.removeChild(container);
                        } else if (document.body.contains(container)) {
                            document.body.removeChild(container);
                        }
                    }, 250);
                } catch (err) {
                    console.error('Error removing container on outside click:', err);
                }
            }
        });
    } catch (err) {
        console.error('Error adding outside click handler:', err);
    }
}
